using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for a given resource ID.")]
    public static async Task<string> FetchResource(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The resource ID to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {ResourceId}", resourceId);

        var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);

        logger.LogInformation("Successfully fetched resource {ResourceId}", resourceId);
        return json;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Summarize the provided text into a concise overview.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize")] string content,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "bullet-points" => "Summarize the following text as a list of bullet points.",
            "detailed" => "Provide a detailed summary of the following text, preserving key nuances.",
            _ => "Provide a brief, concise summary of the following text."
        };

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.System, systemInstruction),
            new(Microsoft.Extensions.AI.ChatRole.User, content)
        ];
    }
}

